Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    long long min_residual = x;
    long long num = 0;
    long long den = 1;

    for (long long denom = 1; denom <= n; ++denom) {
        long long a_start = max(x * denom / y - 10, 0LL);
        for (int offset = 0; offset < 20; ++offset) {
            long long a_candidate = a_start + offset;
            long long diff_value = abs(x * denom - a_candidate * y);
            if (min_residual * denom > diff_value * den) {
                min_residual = diff_value;
                num = a_candidate;
                den = denom;
            } else if (min_residual * denom == diff_value * den) {
                if (den > denom || (den == denom && num > a_candidate)) {
                    num = a_candidate;
                    den = denom;
                }
            }
        }
    }
    cout << num << "/" << den << endl;
}
</original_code>
